"""Beat times (voice seconds, read off the whisper words) -> beats.json; captions with per-word times -> caps_<lang>.json;
vo_<lang>_p.wav = the take with a 3 s silence inserted after the quiz question (the script's "пауза 3 с").
All times written out are voice times AFTER the pause is inserted."""
import json, subprocess
PAUSE = 3.0
CUT = {'ru': 57.3, 'kk': 60.5}
KEYS = 'show c15 abul ulus nomad cap but orys kj decide go mog shu koz esen kh y1468 flow shai y1500 sam name today quiz qq opts o2 o3 ans two cta link vend'.split()
RAW = {'ru': [4.68, 5.84, 8.38, 10.86, 12.94, 14.42, 16.02, 18.44, 20.1, 21.04, 22.84, 24.04, 25.22, 25.88, 27.52, 28.82, 31.18, 34.64, 38.2, 40.3, 42.82,
              43.82, 46.64, 49.1, 51.46, 53.94, 54.92, 55.94, 57.82, 61.32, 63.7, 67.7, 69.5],
       'kk': [4.84, 6.22, 8.1, 10.64, 12.66, 14.64, 16.28, 18.84, 20.32, 21.94, 23.38, 24.54, 25.58, 26.06, 28.5, 30.36, 33.0, 36.12, 40.06, 42.94, 45.42,
              46.88, 49.8, 52.66, 53.98, 56.1, 57.4, 58.66, 61.06, 64.9, 67.0, 71.22, 73.3]}
S = {'ru': [(0, 'Наших предков когда-то называли «узбеками».'), (2.84, 'Пока два султана не откочевали.'), (4.68, 'Покажу на карте.'), (5.84, 'XV век.'),
            (7.22, 'Этими землями правил Абулхаир-хан.'), (9.58, 'Его государство называли «Узбекским улусом»,'), (12.34, 'а народ — «кочевыми узбеками».'),
            (14.42, 'Столица — Сыганак.'), (16.02, 'Но жёсткую власть хана терпели не все.'), (18.44, 'Потомки Орыс-хана, султаны Керей и Жанибек, решили откочевать.'),
            (22.84, 'Они увели своих людей в Моголистан, в долину Шу и на Козыбасы.'), (26.84, 'Там их принял Есен-Буга хан.'), (28.82, 'Так началось Казахское ханство.'),
            (31.18, 'В 1468 году Абулхаир умер.'), (34.64, 'И большая часть его кочевников ушла к Керею и Жанибеку.'),
            (38.2, 'А внук Абулхаира Мухаммед Шейбани в 1500 году ушёл на юг и взял Самарканд.'), (43.82, 'Так имя «узбек» переехало в Мавераннахр.'),
            (46.64, 'Нынешние узбеки получили это имя оттуда.'), (49.1, 'Вопрос с ЕНТ.'), (51.46, 'Куда откочевали Керей и Жанибек?'),
            (53.86, 'В Мавераннахр, Моголистан или Ногайскую Орду?'), (57.82, 'Правильно: в Моголистан, на Шу и Козыбасы.'), (61.32, 'Из одного улуса вышли два народа.'),
            (63.7, 'Такие вопросы часто бывают на ЕНТ,'), (66.14, 'мы разбираем их по одному.'), (67.7, None)],
     'kk': [(0, 'Бабаларымызды бір кезде «өзбек» деп атаған.'), (2.96, 'Екі сұлтан көшіп кеткенге дейін.'), (4.84, 'Картадан көрсетемін.'), (6.22, 'XV ғасыр.'),
            (7.52, 'Бұл жерді Әбілқайыр хан билеген.'), (9.7, 'Оның мемлекетін «Өзбек ұлысы»,'), (11.94, 'ал халқын «көшпелі өзбектер» деп атаған.'),
            (14.64, 'Астанасы — Сығанақ.'), (16.28, 'Бірақ ханның қатал билігіне бәрі көнбеді.'),
            (18.84, 'Орыс ханның ұрпақтары — Керей мен Жәнібек сұлтандар — көшуге бел буды.'), (23.38, 'Олар өз елін бастап, Моғолстанға, Шу мен Қозыбасы жеріне көшті.'),
            (27.74, 'Мұнда оларды Есен-Бұға хан қарсы алды.'), (30.36, 'Осылай Қазақ хандығы басталды.'), (33.0, '1468 жылы Әбілқайыр қайтыс болды.'),
            (36.12, 'Сонда оның көшпелі елінің көбі Керей мен Жәнібекке барып қосылды.'),
            (40.06, 'Ал Әбілқайырдың немересі Мұхаммед Шайбани 1500 жылы оңтүстікке кетіп, Самарқандты алды.'), (46.88, '«Өзбек» деген ат солай Мәуереннахрға көшті.'),
            (49.8, 'Бүгінгі өзбектер бұл атты содан алған.'), (52.66, 'ҰБТ сұрағы.'), (53.98, 'Керей мен Жәнібек қайда көшті?'),
            (56.1, 'Мәуереннахрға, Моғолстанға әлде Ноғай Ордасына?'), (61.06, 'Дұрыс жауап: Моғолстан, Шу мен Қозыбасы.'), (64.9, 'Бір ұлыстан екі халық шықты.'),
            (67.0, 'Мұндай сұрақтар ҰБТ-да жиі келеді,'), (69.2, 'біз оларды бір-бірлеп талдаймыз.'), (71.22, None)]}
sh = lambda L, t: round(t + PAUSE if t >= CUT[L] else t, 2)
out = {}
for L in ('ru', 'kk'):
    out[L] = {k: sh(L, v) for k, v in zip(KEYS, RAW[L])}; out[L]['hook'] = 0; out[L]['pause'] = CUT[L]
    W = json.load(open(f'words_{L}.json')); caps = []
    for (t0, s), (t1, _) in zip(S[L], S[L][1:]):
        end = max([w[1] for w in W if t0 - .05 <= w[0] < t1 - .05] or [t1 - .3])
        words = s.replace(' —', '').split(' '); tot = sum(len(w) + 2 for w in words); t = t0; tw = []
        for w in words: d = (end - t0) * (len(w) + 2) / tot; tw.append([w, sh(L, t), sh(L, t + d)]); t += d
        cur = []
        for w in tw:
            cur.append(w)
            if len(cur) == 3 or (len(cur) == 2 and len(' '.join(c[0] for c in cur)) > 16) or w[0][-1] in ',.?:':
                caps.append([cur[0][1], cur[-1][2], cur]); cur = []
        if cur: caps.append([cur[0][1], cur[-1][2], cur])
    json.dump(caps, open(f'caps_{L}.json', 'w'), ensure_ascii=False)
    subprocess.run(['ffmpeg', '-loglevel', 'error', '-y', '-i', f'vo_{L}.mp3', '-filter_complex',
                    f'[0:a]aresample=48000,asplit[a][b];[a]atrim=0:{CUT[L]},asetpts=N/SR/TB[x];[b]atrim={CUT[L]},asetpts=N/SR/TB[y];'
                    f'anullsrc=r=48000:cl=mono,atrim=0:{PAUSE}[z];[x][z][y]concat=n=3:v=0:a=1,aformat=channel_layouts=mono', '-ac', '1', f'vo_{L}_p.wav'], check=True)
    print(L, len(caps), out[L]['vend'])
json.dump(out, open('beats.json', 'w'), indent=0)
